import {getLanguage} from './i18n.mjs';
const iw=(th,en)=>getLanguage()==='en'?en:th;
export function renderIndustryDevices(){const rows=[
 ['ร้านอาหาร','Restaurant','POS, เครื่องรับชำระ, เราเตอร์, UPS, สแกนเนอร์รับสินค้า','POS, payment terminal, router, UPS, receiving scanner','จอครัว KDS, เครื่องพิมพ์ครัว, เซนเซอร์และตู้เย็น, คิวปรุงและส่งมอบ','KDS, kitchen printer, cold-storage sensor and preparation/handover queues','ความร้อน ไอน้ำ คราบ การทำความสะอาด ความอ่านง่ายของใบงานและข้อมูลสารก่อภูมิแพ้ตาม SOP','Heat, steam, grease, cleaning, readable tickets and allergen information per SOP'],
 ['ค้าปลีก','Retail','ใช้ฐาน POS, เครื่องรับชำระ, เราเตอร์และสแกนเนอร์แบบเดียวกันได้ หากรุ่นและไดรเวอร์รองรับ','Can reuse POS, payment, network and scanner families when models and drivers support the workflow','สแกนเนอร์หน้าเคาน์เตอร์ เครื่องพิมพ์ราคา เครื่องชั่งหรือ RFID ตามสินค้า','Checkout scanner, price-label printer, scale or RFID as appropriate','ชนิดบาร์โค้ด ความเร็วสแกน การคืนสินค้า SKU/ราคา และการเชื่อมเครื่องชั่ง','Barcode type, scan throughput, returns, SKU/pricing and scale integration'],
 ['ร้านบริการ','Service business','ใช้แท็บเล็ต POS, เครื่องรับชำระและเครื่องพิมพ์ใบเสร็จร่วมตระกูลได้','Can share tablet/POS, payment and receipt-printer families','ระบบนัดหมาย ใบงาน ช่าง ผู้ให้บริการ และเครื่องมือเฉพาะ เช่น ร้านดูแลรถ','Appointment and job-ticket system, assigned staff and specialized tools, e.g. car-care equipment','เวลาแต่ละงาน ความสามารถพนักงาน หลักฐานก่อน–หลัง และสภาพเปียกชื้นของพื้นที่','Job duration, staff capability, before/after evidence and wet-work conditions'],
 ['โรงงาน','Manufacturing','ใช้เครือข่าย UPS gateway และสแกนเนอร์แนวคิดเดียวกัน รุ่นใช้งานอาจต้องเปลี่ยน','Shares networking, UPS, gateway and scanning concepts; physical models may differ','Industrial PC/HMI, PLC, เครื่องพิมพ์ล็อต สแกนเนอร์ทนทาน เซนเซอร์ และ MES/SCADA ตามกระบวนการ','Industrial PC/HMI, PLC, lot printer, rugged scanner, sensors and process-specific MES/SCADA','ฝุ่น น้ำ แรงสั่น อุณหภูมิ EMC ระยะอ่าน รอบเวลาผลิต และการแยก IT/OT ตามข้อกำหนดโรงงาน','Dust, water, vibration, temperature, EMC, scan range, cycle time and IT/OT separation per plant requirements']
 ];return `<section class="panel activity" id="industry-devices"><div class="panel-header"><h2>${iw('อุปกรณ์ใช้ข้ามอุตสาหกรรมได้แค่ไหน','Which devices can be shared across industries?')}</h2></div><div class="industry-device-notes"><p><strong>${iw('ใช้ร่วมได้บางส่วน แต่พอร์ตเหมือนกันไม่ได้แปลว่าใช้แทนกันได้ทันที','Some equipment can be shared, but matching ports do not guarantee interchangeability.')}</strong></p><p>${iw('โมเดล 3D นี้ใช้ร้านอาหารเป็นตัวอย่าง ไม่ได้แสดงเครื่องจักรเฉพาะของทุกอุตสาหกรรม การสลับธุรกิจในแถบด้านบนเปลี่ยนพื้นที่ทดลองธุรกิจ ไม่ได้เปลี่ยนรุ่นอุปกรณ์หรือแบบติดตั้ง 3D','The 3D model illustrates a restaurant, not every industry-specific machine. The business switcher changes the business demo context; it does not change the 3D device models or installation design.')}</p></div><div class="industry-device-table"><table class="insight-table"><thead><tr><th>${iw('อุตสาหกรรม','Industry')}</th><th>${iw('ส่วนที่ใช้ร่วมได้','Shared base')}</th><th>${iw('ส่วนเฉพาะงาน','Specialized equipment/workflow')}</th><th>${iw('ตรวจอะไรก่อนใช้แทนกัน','Interchangeability checks')}</th></tr></thead><tbody>${rows.map(([th,en,baseTh,baseEn,specificTh,specificEn,checkTh,checkEn])=>`<tr><td>${iw(th,en)}</td><td>${iw(baseTh,baseEn)}</td><td>${iw(specificTh,specificEn)}</td><td>${iw(checkTh,checkEn)}</td></tr>`).join('')}</tbody></table></div><div class="industry-device-notes"><p>${iw('ก่อนย้ายอุปกรณ์: ตรวจ 1) งานและกำลังรับงาน 2) สภาพแวดล้อมและระดับทนทาน 3) พอร์ต driver/SDK และข้อมูลที่ส่ง 4) อุปกรณ์สิ้นเปลือง/บริการซ่อม 5) การสอบเทียบและข้อกำหนดพื้นที่ใช้งาน 6) พฤติกรรมเมื่อเน็ตหรืออุปกรณ์ล้มเหลว','Before reuse, check: 1) task and throughput; 2) environmental ratings; 3) ports, drivers/SDK and payload; 4) consumables and repair support; 5) calibration and local requirements; 6) network/device failure behavior.')}</p><p>${iw('ตัวอย่างจริง: Zebra แยกสแกนเนอร์มือถือ แบบตั้งประจำ และรุ่นอุตสาหกรรม ส่วน Epson มีเครื่องพิมพ์ครัวที่ออกแบบรับความร้อนและความชื้น จึงไม่ควรสรุปว่าเครื่องพิมพ์ใบเสร็จหน้าร้านทุกรุ่นเหมาะกับครัว','Real examples: Zebra distinguishes handheld, fixed and industrial scanner models. Epson offers kitchen printers designed for heat and humidity, so not every front-counter receipt printer is suitable for a kitchen.')}</p><p>${iw('PLC/ระบบความปลอดภัยเครื่องจักรไม่ใช่ POS การเชื่อมข้อมูลธุรกิจไม่ควรใช้แทนตัวควบคุมความปลอดภัย ต้องให้ผู้รับผิดชอบเครื่องจักรตรวจรับ','A PLC or machine safety system is not a POS. Business integration must not substitute for safety control; responsible machine specialists must approve the design.')}</p><p>${iw('อ้างอิงผู้ผลิต','Manufacturer references')}: <a href="https://www.zebra.com/us/en/products/scanners.html" target="_blank" rel="noopener">Zebra scanner families</a> · <a href="https://www.epson.com.au/products/receipt-printers/kitchen-printers/" target="_blank" rel="noopener">Epson kitchen printers</a> · <a href="https://sieportal.siemens.com/en-be/products-services/5100003" target="_blank" rel="noopener">Siemens industrial PCs</a></p></div></section>`;}
